def recur(start: str, rule: str, count: int) -> list[str]:
    from datetime import date, timedelta
    from calendar import monthrange

    start_date = date.fromisoformat(start)
    tokens = rule.split()
    frequency = tokens[0]
    step = int(tokens[1])
    weekdays = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                "FR": 4, "SA": 5, "SU": 6}
    result = []

    if frequency == "DAILY":
        current = start_date
        for i in range(count):
            result.append(current.isoformat())
            if i + 1 < count:
                current += timedelta(days=step)

    elif frequency == "WEEKLY":
        days = sorted(weekdays[day] for day in tokens[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())

        while len(result) < count:
            for day in days:
                current = week_start + timedelta(days=day)
                if current >= start_date:
                    result.append(current.isoformat())
                    if len(result) == count:
                        break
            if len(result) < count:
                week_start += timedelta(weeks=step)

    elif frequency == "MONTHLY":
        month_index = start_date.year * 12 + start_date.month - 1

        while len(result) < count:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            last_day = monthrange(year, month)[1]

            if len(tokens) == 3:
                requested_day = int(tokens[2])
                day = last_day if requested_day == -1 else requested_day
            else:
                ordinal = int(tokens[2])
                weekday = weekdays[tokens[3]]
                if ordinal == -1:
                    last_weekday = date(year, month, last_day).weekday()
                    day = last_day - (last_weekday - weekday) % 7
                else:
                    first_weekday = date(year, month, 1).weekday()
                    day = 1 + (weekday - first_weekday) % 7 + 7 * (ordinal - 1)

            if day <= last_day:
                current = date(year, month, day)
                if current >= start_date:
                    result.append(current.isoformat())
            month_index += step

    else:
        month, day = map(int, tokens[2].split("-"))
        year = start_date.year

        while len(result) < count:
            if day <= monthrange(year, month)[1]:
                current = date(year, month, day)
                if current >= start_date:
                    result.append(current.isoformat())
            year += step

    return result
